import pandas as pd, numpy as np, ast
df=pd.read_excel('model_evaluation_sample.xlsx')
G={'Gen_z':['#trending','#viral','#yolo'],'Millennials':['#foodie','#travel','#workhard'],'Gen_x':['#career','#familylife','#retirement'],'Baby Boomers':['#classics','#history','#grandparents']}
m={t:k for k,v in G.items() for t in v}
r=df.Hashtags.map(lambda s:m[ast.literal_eval(s)[0]]).values; a=df['Actual Class'].values; p=df['Predicted Class'].values
ks=np.unique(a)
def bal(pr,aa): return np.mean([(pr[aa==k]==k).mean() for k in ks])
rng=np.random.default_rng(1); d=[]
for _ in range(5000):
  i=rng.integers(0,1000,1000); d.append(bal(r[i],a[i])-bal(p[i],a[i]))
d=np.array(d); print(np.percentile(d,[2.5,97.5]),(d<=0).mean())
